const BASE='http://localhost:4310';
const A='alice@east.test';
const h=(k)=>({'Content-Type':'application/json','X-Actor-Email':A,...(k?{'Idempotency-Key':k}:{})});
async function bulk(key,course){
  const t0=performance.now();
  const r=await fetch(BASE+'/api/certificates/bulk-issue',{method:'POST',headers:h(key),body:JSON.stringify({courseId:course})});
  const b=await r.json();
  return {ms:+(performance.now()-t0).toFixed(1),status:r.status,replay:r.headers.get('idempotent-replay'),issued:b.summary?.issued,op:b.operationId};
}
// 1) sequential replay
console.log('seq#1',await bulk('p-seq','course-east-safety'));
console.log('seq#2',await bulk('p-seq','course-east-safety'));
// 2) 5 "concurrent" — measure per-request latency to see if the wait/IN_PROGRESS path is ever entered
const rs=await Promise.all(Array.from({length:5},()=>bulk('p-conc','course-east-privacy')));
console.log('conc',rs);
// 3) A3 misuse
const misuse=await fetch(BASE+'/api/certificates/bulk-issue',{method:'POST',headers:h('p-seq'),body:JSON.stringify({courseId:'course-east-privacy'})});
console.log('misuse',misuse.status,await misuse.text());
EOF
