const r2=await fetch(BASE+'/api/certificates/export?'+qs,{headers:H}); const t2=await r2.text();
console.log('byte-identical=',t1===t2);
// how long does the export actually stay "in flight"? measure list latency while export runs at various offsets
for (const delay of [0,20,100,300,Math.max(0,dur-50)]) {
  const p=fetch(BASE+'/api/certificates/export?'+qs,{headers:H});
  await new Promise(r=>setTimeout(r,delay));
  const lt=Date.now();
  const lr=await fetch(BASE+'/api/certificates?pageSize=5',{headers:H});
  await lr.text();
  console.log(`list during export @+${delay}ms → ${lr.status} in ${Date.now()-lt}ms`);
  await p.then(x=>x.text());
}
