import express from '/Users/zhihaomeng/Documents/ocean_ai_real/node_modules/express/index.js';
import { once } from 'node:events';
const app=express();
app.get('/slow', async (req,res)=>{
  res.setHeader('Content-Type','text/csv');
  const events=[];
  req.on('close',()=>events.push('req.close'));
  res.on('close',()=>events.push('res.close'));
  res.on('error',(e)=>events.push('res.error:'+e.code));
  let i=0;
  try{
    while(i<50){
      const ok=res.write('x'.repeat(100000));
      if(!ok){ const t=Date.now(); await once(res,'drain'); events.push('drained@'+i+' in '+(Date.now()-t)+'ms'); }
      i++;
      await new Promise(r=>setImmediate(r));
    }
    console.log('COMPLETED loop', JSON.stringify(events));
    res.end();
  }catch(e){ console.log('THREW',e.message, JSON.stringify(events)); }
});
app.listen(4399,()=>console.log('abort-server up'));
EOF
node abort-server.mjs > /tmp/abort-server.log 2>&1 &
sleep 1.2
