const fs=require("node:fs"),c=require("node:crypto");
const load=(f)=>fs.readFileSync("ai/sessions/"+f,"utf8").split("\n").filter(Boolean).map(l=>c.createHash("sha1").update(l).digest("hex"));
const a=load("session-38ebbc55-6199-4a49-9570-296069b77136.jsonl");
const b=load("session-fbf0c869-7f7c-407a-ad3c-ec0ce7d681c3.jsonl");
const sa=new Set(a);
const shared=b.filter(h=>sa.has(h)).length;
console.log("planning records:",a.length,"main records:",b.length,"shared identical records:",shared);
console.log("main is superset of planning?", a.every(h=>new Set(b).has(h)));
'","description":"Quantify session overlap"}

