{"command":"cd /tmp && cat > probe7.mjs <<'EOF'
const BASE='http://localhost:4310';
const A={'Content-Type':'application/json','X-Actor-Email':'alice@east.test'};
const post=(p,body,key)=>fetch(BASE+p,{method:'POST',headers:{...A,...(key?{'Idempotency-Key':key}:{})},body:JSON.stringify(body??{})});
// issue to course-east-privacy with new key k1
let r=await post('/api/certificates/bulk-issue',{courseId:'course-east-privacy'},'rev-1');
let b=await r.json();
console.log('issue#1', b.summary, b.outcomes.map(o=>o.learnerName+':'+o.status));
const certId=b.outcomes.filter(o=>o.status==='issued')[0].certificateId;
// revoke it
r=await post(`/api/certificates/${certId}/revoke`); b=await r.json();
console.log('revoke →', b.status);
// re-run bulk issue for the same course with a NEW key
r=await post('/api/certificates/bulk-issue',{courseId:'course-east-privacy'},'rev-2'); b=await r.json();
console.log('issue#2 (after revoke, new key)', b.summary, b.outcomes.map(o=>o.learnerName+':'+o.status+'/'+(o.reason??'')));
// what does the learner see in the list?
const l=await (await fetch(BASE+'/api/certificates?search=Tom&pageSize=10',{headers:A})).json();
console.log('list search Tom →', l.items.map(i=>i.serialNumber+' '+i.status));
EOF
node probe7.mjs","description":"Test re-issue after revocation semantics","timeoutMs":120000}

